AOS.init({duration:1000,once:true,offset:100});window.addEventListener('load',()=>{setTimeout(()=>{document.getElementById('loading-screen').style.display='none'},1500)});const mobileMenuBtn=document.getElementById('mobile-menu-btn');const mobileMenu=document.getElementById('mobile-menu');if(mobileMenuBtn&&mobileMenu){mobileMenuBtn.addEventListener('click',()=>{mobileMenu.classList.toggle('hidden')});mobileMenu.querySelectorAll('a').forEach(link=>{link.addEventListener('click',()=>{mobileMenu.classList.add('hidden')})})}window.addEventListener('scroll',()=>{const navbar=document.getElementById('navbar');if(navbar){if(window.scrollY>50){navbar.classList.add('navbar-scroll')}else{navbar.classList.remove('navbar-scroll')}}});document.querySelectorAll('a[href^="#"]').forEach(anchor=>{anchor.addEventListener('click',function(e){e.preventDefault();const target=document.querySelector(this.getAttribute('href'));if(target){target.scrollIntoView({behavior:'smooth',block:'start'})}})});const contactForm=document.getElementById('contact-form');const successMessage=document.getElementById('success-message');if(contactForm&&successMessage){contactForm.addEventListener('submit',(e)=>{e.preventDefault();successMessage.classList.remove('hidden');contactForm.reset();setTimeout(()=>{successMessage.classList.add('hidden')},5000)})}const newsletterForm=document.getElementById('newsletter-form');if(newsletterForm){newsletterForm.addEventListener('submit',(e)=>{e.preventDefault();const email=e.target.querySelector('input[type="email"]').value;alert('¡Gracias por suscribirte a nuestro newsletter VIP!');newsletterForm.reset()})}const calendarDays=document.querySelectorAll('.calendar-day');let selectedDate=null;calendarDays.forEach(day=>{day.addEventListener('click',()=>{if(day.textContent&&!day.classList.contains('text-gray-400')){if(selectedDate){selectedDate.classList.remove('selected')}day.classList.add('selected');selectedDate=day}})});const serviceCheckboxes=document.querySelectorAll('input[type="checkbox"]');const totalElement=document.querySelector('.text-2xl.font-bold.text-gold');if(serviceCheckboxes.length>0&&totalElement){serviceCheckboxes.forEach(checkbox=>{checkbox.addEventListener('change',calculateTotal)})}function calculateTotal(){let total=0;const prices={'Facial Premium':299,'Tratamiento Corporal':199,'Spa & Wellness':399,'Tratamiento Avanzado':499};serviceCheckboxes.forEach(checkbox=>{if(checkbox.checked){const label=checkbox.closest('label');const serviceName=label.querySelector('.font-semibold').textContent;if(prices[serviceName]){total+=prices[serviceName]}}});totalElement.textContent=`$${total}`}const timeSlots=document.querySelectorAll('.grid.grid-cols-3 button');let selectedTime=null;timeSlots.forEach(slot=>{slot.addEventListener('click',()=>{if(selectedTime){selectedTime.classList.remove('bg-gold','text-white');selectedTime.classList.add('border','border-gold')}slot.classList.remove('border','border-gold');slot.classList.add('bg-gold','text-white');selectedTime=slot})});window.addEventListener('scroll',()=>{const scrolled=window.pageYOffset;const parallax=document.querySelector('.parallax');if(parallax){const speed=0.5;parallax.style.transform=`translateY(${scrolled*speed}px)`}});const observerOptions={threshold:0.1,rootMargin:'0px 0px -50px 0px'};const observer=new IntersectionObserver((entries)=>{entries.forEach(entry=>{if(entry.isIntersecting){entry.target.classList.add('loading-animation')}})},observerOptions);document.querySelectorAll('section').forEach(section=>{observer.observe(section)});
